import threading


class JobQueue:
    def __init__(self, job_ids):
        self.jobs = {job_id: {'state': 'pending', 'owner': None, 'completions': 0}
                     for job_id in job_ids}
        # Reentrant so a callback may synchronously invoke a second worker's
        # claim from the same thread without deadlocking.
        self._lock = threading.RLock()

    def claim(self, job_id, worker_id, on_attempt=None):
        with self._lock:
            job = self.jobs[job_id]
            if on_attempt is not None:
                on_attempt()
            # The state is checked only after the callback: a second worker's
            # claim interleaved inside the callback may have already acquired
            # the job. At most one worker can acquire each job, whichever
            # attempt gets there first.
            if job['state'] != 'pending':
                return False
            job['state'] = 'claimed'
            job['owner'] = worker_id
            return True

    def complete(self, job_id, worker_id):
        with self._lock:
            job = self.jobs[job_id]
            if job['state'] != 'claimed' or job['owner'] != worker_id:
                return False
            job['state'] = 'complete'
            job['completions'] += 1
            return True

