class Worker:
    def __init__(self, name, queue):
        self.name = name
        self.queue = queue

    def take(self, job_id, on_attempt=None):
        return self.queue.claim(job_id, self.name, on_attempt)

    def finish(self, job_id):
        return self.queue.complete(job_id, self.name)
